				\usepackage{upgreek}
				\setlength{\oddsidemargin}{-69pt}
				\begin{document}$${\Delta {{\updelta }}}_{{{\rm{W}}}}={[{({{{\updelta }}}_{{{\rm{HN}}}}^{{{\rm{bound}}}}-{{{\updelta }}}_{{{\rm{HN}}}}^{{{\rm{free}}}})}^{2}+{({{{\updelta }}}_{{{\rm{H\alpha}}}}^{{{\rm{bound}}}}-{{{\updelta }}}_{{{\rm{H\alpha}}}}^{{{\rm{free}}}})}^{2}]}^{1/2}$$\end{document}ΔδW=[(δHNbound−δHNfree)2+(δHαbound−δHαfree)2]1/2
